SELECT fn_cp_import_case('biens-vol-materiel-chantier-nuit', '{"slug": "biens-vol-materiel-chantier-nuit", "title": "La clôture est découpée, un engin manque", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 4 heures. Vous êtes appelée sur un chantier de construction où le gardien de nuit a découvert une section de la clôture périphérique soigneusement découpée, constatant qu''un engin de chantier de valeur importante a disparu du site durant la nuit. Ce site étendu, plongé dans l''obscurité et parsemé de matériaux et d''équipements divers, complique considérablement les constatations et fait craindre la présence encore possible des auteurs quelque part sur cette vaste surface.\n\nCette découpe méthodique de la clôture, réalisée avec un outillage approprié, témoigne d''une préparation qui dépasse largement l''improvisation, cette professionnalisation du mode opératoire suggérant une organisation structurée autour du vol de ce type d''engin de valeur.\n\nCette situation impose de sécuriser méthodiquement ce site étendu avant toute autre considération, tout en préservant les traces de cette effraction qui pourraient s''avérer précieuses pour identifier cette organisation structurée derrière ce vol.", "questions": [{"position": 1, "max_points": 5, "label": "Comment sécurisez-vous ce site étendu avant toute autre considération, compte tenu du risque de présence encore possible des auteurs ?", "hint": "L''étendue et l''obscurité de ce chantier nécessitent une sécurisation méthodique qui ne néglige aucune zone où les auteurs pourraient encore se trouver.", "perfect": "Je procède à une sécurisation méthodique de l''ensemble de ce site étendu, cette vérification restant prioritaire compte tenu du risque que les auteurs de cette effraction soient encore présents quelque part sur cette vaste surface.\n\nJe sollicite un renfort suffisant pour couvrir efficacement l''ensemble de cette zone, cette étendue rendant une vérification solitaire à la fois risquée et insuffisamment méthodique.\n\nJe reste attentive aux dangers spécifiques que peut présenter ce chantier dans l''obscurité, notamment les matériaux et équipements divers qui pourraient constituer des risques pour ma propre sécurité durant cette vérification.\n\nJe coordonne cette sécurisation avec le gardien de nuit qui connaît la configuration précise de ce site, cette collaboration facilitant une couverture plus efficace de l''ensemble de cette surface étendue.", "points": [{"position": 1, "label": "Procéder à une sécurisation méthodique de l''ensemble du site", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : risque de présence des auteurs sur cette vaste surface.", "groups": [{"position": 1, "keywords": ["sécurisation méthodique", "site étendu", "auteurs possiblement présents"]}]}, {"position": 2, "label": "Solliciter un renfort suffisant pour couvrir cette zone", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Vérification solitaire risquée et insuffisante.", "groups": [{"position": 1, "keywords": ["renfort sollicité", "couverture efficace", "vérification solitaire évitée"]}]}, {"position": 3, "label": "Rester attentive aux dangers spécifiques du chantier dans l''obscurité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Matériaux et équipements constituant des risques.", "groups": [{"position": 1, "keywords": ["dangers spécifiques", "obscurité", "sécurité personnelle"]}]}, {"position": 4, "label": "Coordonner cette sécurisation avec le gardien de nuit", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Connaissance de la configuration du site.", "groups": [{"position": 1, "keywords": ["coordination avec gardien", "configuration connue", "couverture facilitée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment préservez-vous les traces de cette effraction méthodique de la clôture ?", "hint": "La découpe méthodique de cette clôture constitue un élément technique précieux qui doit être préservé avec soin pour l''enquête.", "perfect": "Je sécurise le périmètre immédiat de cette section de clôture découpée, cette préservation étant essentielle pour permettre des constatations techniques approfondies sur cette effraction.\n\nJe m''abstiens de toute manipulation de cette section découpée avant l''intervention des services compétents en constatations, cette rigueur étant nécessaire pour ne pas compromettre les traces qui pourraient y être présentes.\n\nJe recherche également les traces de déplacement de cet engin volé, comme des empreintes de pneus ou de chenilles, ces éléments pouvant orienter utilement l''enquête sur les circonstances de cette disparition.\n\nJe consigne avec précision les caractéristiques de cette découpe, notamment sa précision et l''outillage qui semble avoir été utilisé, ces éléments techniques pouvant révéler le professionnalisme des auteurs.", "points": [{"position": 1, "label": "Sécuriser le périmètre immédiat de la section découpée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : préservation pour des constatations approfondies.", "groups": [{"position": 1, "keywords": ["périmètre sécurisé", "section découpée", "constatations approfondies"]}]}, {"position": 2, "label": "S''abstenir de toute manipulation avant les constatations", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rigueur nécessaire pour ne pas compromettre les traces.", "groups": [{"position": 1, "keywords": ["pas de manipulation", "traces préservées", "rigueur nécessaire"]}]}, {"position": 3, "label": "Rechercher les traces de déplacement de l''engin volé", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Empreintes de pneus ou de chenilles orientant l''enquête.", "groups": [{"position": 1, "keywords": ["traces de déplacement", "empreintes recherchées", "enquête orientée"]}]}, {"position": 4, "label": "Consigner les caractéristiques précises de cette découpe", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Précision et outillage révélant le professionnalisme.", "groups": [{"position": 1, "keywords": ["caractéristiques consignées", "outillage utilisé", "professionnalisme révélé"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment orientez-vous l''enquête vers l''organisation structurée qui semble se cacher derrière ce vol méthodique ?", "hint": "La professionnalisation de ce mode opératoire suggère une organisation qui dépasse le simple vol d''opportunité, cette dimension méritant d''être explorée.", "perfect": "Je recueille avec précision les caractéristiques techniques de cet engin disparu, notamment son numéro de série et ses éventuels dispositifs de géolocalisation qui pourraient faciliter son identification ultérieure.\n\nJe m''intéresse à la valeur et à la revente potentielle de ce type d''engin, cette dimension économique pouvant orienter vers des filières spécialisées dans ce type de trafic de matériel professionnel.\n\nJe recueille auprès du gardien et des responsables du chantier tout élément sur d''éventuels repérages ou visites suspectes qui auraient précédé ce vol, ces observations pouvant révéler une préparation antérieure.\n\nJe transmets l''ensemble de ces éléments aux services compétents pour orienter l''enquête vers une éventuelle organisation structurée, cette dimension collective dépassant le seul traitement de ce vol isolé.", "points": [{"position": 1, "label": "Recueillir les caractéristiques techniques et de géolocalisation de l''engin", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : numéro de série facilitant l''identification.", "groups": [{"position": 1, "keywords": ["caractéristiques techniques", "géolocalisation", "identification facilitée"]}]}, {"position": 2, "label": "S''intéresser à la valeur et à la revente potentielle de cet engin", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Filières spécialisées dans ce type de trafic.", "groups": [{"position": 1, "keywords": ["valeur de revente", "filières spécialisées", "trafic de matériel"]}]}, {"position": 3, "label": "Recueillir les éléments sur d''éventuels repérages antérieurs", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Observations révélant une préparation antérieure.", "groups": [{"position": 1, "keywords": ["repérages recherchés", "visites suspectes", "préparation antérieure"]}]}, {"position": 4, "label": "Transmettre pour orienter vers une organisation structurée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Dimension collective dépassant le vol isolé.", "groups": [{"position": 1, "keywords": ["organisation structurée", "dimension collective", "vol non isolé"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-differend-restitution-objet-saisi', '{"slug": "biens-differend-restitution-objet-saisi", "title": "Il réclame son téléphone depuis quatre mois", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 11 heures. Un homme se présente au commissariat pour réclamer, avec une exaspération manifeste mais compréhensible, la restitution de son téléphone portable saisi quatre mois plus tôt dans le cadre d''une procédure dont il ne maîtrise ni l''état d''avancement ni les raisons du délai qui s''accumule sans qu''aucune information ne lui ait été communiquée depuis. Cette exaspération, qui traduit une frustration légitime face à une procédure dont il ne perçoit ni la logique ni l''échéance, se heurte à votre propre incapacité à influencer directement les délais de traitement de cette procédure qui ne relève pas de votre seule compétence immédiate.\n\nCette situation, où l''usager exprime une attente compréhensible d''information et de résultat concret, nécessite de gérer cette relation avec transparence tout en étant honnête sur les limites réelles de ce que vous pouvez personnellement lui garantir concernant cette restitution.\n\nCette configuration impose de fournir une information aussi précise que possible sur l''état de cette procédure, sans pour autant promettre un délai que vous ne maîtrisez pas vous-même, cette honnêteté restant préférable à des assurances qui ne pourraient être tenues.", "questions": [{"position": 1, "max_points": 5, "label": "Comment informez-vous précisément cet homme sur l''état de sa procédure sans lui promettre un délai que vous ne maîtrisez pas ?", "hint": "L''information doit être aussi précise que possible sans pour autant s''engager sur un délai qui ne dépend pas de vous, cette honnêteté étant préférable à de fausses promesses.", "perfect": "Je recherche avec lui l''état exact de sa procédure, cette vérification restant nécessaire pour lui fournir une information la plus précise possible sur la situation actuelle de son dossier.\n\nJe lui explique honnêtement que je ne maîtrise pas personnellement les délais de cette procédure, cette transparence étant préférable à une promesse de délai que je ne pourrais pas garantir.\n\nJe reste attentive à son exaspération légitime, cette frustration étant compréhensible face à une absence prolongée d''information sur l''avancement de sa situation.\n\nJe lui indique les services compétents qu''il pourrait solliciter pour obtenir des informations plus précises sur ce dossier spécifique, cette orientation complétant utilement ce que je peux moi-même lui apporter.", "points": [{"position": 1, "label": "Rechercher l''état exact de sa procédure pour une information précise", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information précise sur la situation actuelle.", "groups": [{"position": 1, "keywords": ["état recherché", "information précise", "situation actuelle"]}]}, {"position": 2, "label": "Expliquer honnêtement l''absence de maîtrise des délais", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence préférable à une promesse non garantie.", "groups": [{"position": 1, "keywords": ["honnêteté sur les délais", "pas de fausse promesse", "transparence"]}]}, {"position": 3, "label": "Rester attentive à son exaspération légitime", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Frustration compréhensible face à l''absence d''information.", "groups": [{"position": 1, "keywords": ["exaspération légitime", "frustration compréhensible", "absence d''information"]}]}, {"position": 4, "label": "Indiquer les services compétents pour des informations plus précises", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Orientation complétant l''information apportée.", "groups": [{"position": 1, "keywords": ["services compétents indiqués", "orientation complémentaire", "information complétée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous cette relation avec transparence face à son exaspération, sans reporter la responsabilité sur d''autres services de manière désinvolte ?", "hint": "La transparence sur les limites de votre compétence ne doit pas se transformer en un rejet désinvolte de responsabilité vers d''autres services.", "perfect": "Je reconnais explicitement sa frustration légitime plutôt que de la minimiser, cette validation étant nécessaire avant toute explication sur les limites de ce que je peux personnellement faire.\n\nJe reste attentive à ne pas me défausser de manière désinvolte sur d''autres services, cette orientation devant s''accompagner d''un réel effort de ma part pour l''aider dans la mesure de mes possibilités.\n\nJe lui explique le fonctionnement général de ce type de procédure, cette information contextuelle pouvant l''aider à mieux comprendre les raisons possibles de ce délai sans pour autant le justifier entièrement.\n\nJe m''engage, dans la mesure du possible, à transmettre moi-même sa demande de relance à qui de droit, cette action concrète de ma part pouvant apaiser quelque peu son sentiment d''être ignoré.", "points": [{"position": 1, "label": "Reconnaître explicitement sa frustration légitime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : validation avant toute explication de compétence.", "groups": [{"position": 1, "keywords": ["frustration reconnue", "validation nécessaire", "avant explication"]}]}, {"position": 2, "label": "Ne pas se défausser de manière désinvolte sur d''autres services", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réel effort d''aide dans la mesure des possibilités.", "groups": [{"position": 1, "keywords": ["pas de défausse désinvolte", "effort réel", "aide dans la mesure du possible"]}]}, {"position": 3, "label": "Expliquer le fonctionnement général de ce type de procédure", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information contextuelle sans justifier entièrement le délai.", "groups": [{"position": 1, "keywords": ["fonctionnement expliqué", "information contextuelle", "sans justification totale"]}]}, {"position": 4, "label": "S''engager à transmettre sa demande de relance", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Action concrète apaisant le sentiment d''être ignoré.", "groups": [{"position": 1, "keywords": ["demande transmise", "action concrète", "sentiment apaisé"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment consignez-vous cette démarche pour permettre un suivi effectif de sa situation ?", "hint": "Au-delà de l''échange oral, une consignation précise de cette démarche reste nécessaire pour permettre un suivi effectif de sa demande.", "perfect": "Je consigne avec précision sa demande de restitution ainsi que les éléments de sa procédure qu''il a pu me communiquer, cette documentation étant nécessaire pour un suivi effectif de sa situation.\n\nJe recueille ses coordonnées actualisées pour qu''il puisse être informé de toute évolution de sa procédure, cette précaution évitant que de nouvelles informations ne lui parviennent pas faute de coordonnées à jour.\n\nJe reste attentive à documenter précisément l''échange que nous avons eu, cette traçabilité pouvant être utile s''il devait revenir ultérieurement pour un suivi de cette même demande.\n\nJe l''informe de la possibilité de revenir vers les services compétents s''il ne constate aucune évolution dans un délai raisonnable, cette information pratique lui donnant une perspective concrète pour la suite.", "points": [{"position": 1, "label": "Consigner précisément sa demande et les éléments communiqués", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : documentation pour un suivi effectif.", "groups": [{"position": 1, "keywords": ["demande consignée", "documentation nécessaire", "suivi effectif"]}]}, {"position": 2, "label": "Recueillir ses coordonnées actualisées pour être informé des évolutions", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter que les informations ne lui parviennent pas.", "groups": [{"position": 1, "keywords": ["coordonnées actualisées", "informations transmises", "précaution nécessaire"]}]}, {"position": 3, "label": "Documenter précisément l''échange pour une traçabilité utile", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traçabilité utile pour un suivi ultérieur.", "groups": [{"position": 1, "keywords": ["échange documenté", "traçabilité utile", "suivi ultérieur"]}]}, {"position": 4, "label": "Informer de la possibilité de revenir si aucune évolution n''est constatée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Perspective concrète pour la suite.", "groups": [{"position": 1, "keywords": ["possibilité de retour", "perspective concrète", "délai raisonnable"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-vol-velo-electrique-marquage', '{"slug": "biens-vol-velo-electrique-marquage", "title": "Le vélo est marqué mais il n''a pas le numéro sur lui", "theme_slug": "atteintes-biens", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 18 heures 30. Un homme se présente au commissariat après la découverte du vol de son vélo électrique devant la gare, précisant que ce vélo était marqué avec un dispositif d''identification antivol officiel, mais qu''il ne dispose malheureusement pas sur lui du numéro correspondant à ce marquage, ce document étant resté chez lui. Cet enjeu d''identification, qui pourrait pourtant faciliter significativement la restitution de ce bien s''il venait à être retrouvé, se trouve compromis par cette absence temporaire de l''information nécessaire pour l''exploiter pleinement.\n\nCette situation, où le vélo dispose bien d''un moyen d''identification fiable mais où l''information correspondante n''est pas immédiatement disponible, nécessite de recueillir malgré tout l''ensemble des éléments descriptifs utiles tout en organisant la transmission ultérieure de ce numéro de marquage.\n\nCette configuration impose de ne pas se limiter à une plainte incomplète faute de cette information immédiatement indisponible, mais d''organiser activement son recueil différé pour ne pas perdre le bénéfice de ce dispositif d''identification pourtant existant.", "questions": [{"position": 1, "max_points": 5, "label": "Comment recueillez-vous l''ensemble des éléments descriptifs utiles malgré l''absence immédiate du numéro de marquage ?", "hint": "L''absence de ce numéro ne doit pas empêcher un recueil complet des autres éléments descriptifs disponibles immédiatement.", "perfect": "Je recueille avec précision l''ensemble des caractéristiques descriptives de ce vélo électrique, notamment sa marque, son modèle, sa couleur et tout signe distinctif qu''il pourrait me communiquer immédiatement.\n\nJe m''assure de bien noter l''existence de ce marquage antivol, même en l''absence du numéro précis, cette information restant utile pour orienter la suite du traitement de cette affaire.\n\nJe recueille également les circonstances précises de ce vol devant la gare, notamment l''heure et le mode d''attache utilisé, ces éléments complétant utilement le signalement de ce vélo.\n\nJe reste attentive à ne pas considérer cette plainte comme incomplète du seul fait de l''absence de ce numéro, cette information pouvant être transmise ultérieurement sans invalider le dépôt de plainte initial.", "points": [{"position": 1, "label": "Recueillir précisément les caractéristiques descriptives du vélo", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : marque, modèle, couleur et signes distinctifs.", "groups": [{"position": 1, "keywords": ["caractéristiques recueillies", "marque et modèle", "signes distinctifs"]}]}, {"position": 2, "label": "Noter l''existence du marquage même sans le numéro précis", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information utile pour orienter le traitement.", "groups": [{"position": 1, "keywords": ["marquage noté", "numéro absent", "traitement orienté"]}]}, {"position": 3, "label": "Recueillir les circonstances précises du vol devant la gare", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Heure et mode d''attache complétant le signalement.", "groups": [{"position": 1, "keywords": ["circonstances recueillies", "heure du vol", "mode d''attache"]}]}, {"position": 4, "label": "Ne pas considérer la plainte comme incomplète faute de ce numéro", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transmission ultérieure possible sans invalider le dépôt.", "groups": [{"position": 1, "keywords": ["plainte non incomplète", "transmission ultérieure", "dépôt valide"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment organisez-vous concrètement le recueil différé de ce numéro de marquage ?", "hint": "Ce numéro reste important pour l''exploitation optimale de ce dispositif d''identification, sa transmission ultérieure devant être organisée activement.", "perfect": "Je lui explique clairement l''importance de me transmettre ce numéro de marquage dès que possible, cette information complétant utilement le signalement déjà enregistré.\n\nJe lui indique précisément les modalités selon lesquelles il pourra me transmettre cette information complémentaire, que ce soit par un retour au commissariat ou par un autre moyen de communication approprié.\n\nJe consigne dans mon dossier la mention explicite de cette information à venir, cette précaution évitant que cet élément ne soit oublié dans le traitement de cette affaire.\n\nJe reste attentive à lui rappeler l''utilité de ce dispositif de marquage pour de futurs achats, cette information pouvant lui être utile au-delà du seul traitement de cette affaire actuelle.", "points": [{"position": 1, "label": "Expliquer l''importance de transmettre ce numéro dès que possible", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information complétant le signalement.", "groups": [{"position": 1, "keywords": ["importance expliquée", "transmission rapide", "signalement complété"]}]}, {"position": 2, "label": "Indiquer précisément les modalités de transmission de cette information", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Retour au commissariat ou autre moyen approprié.", "groups": [{"position": 1, "keywords": ["modalités indiquées", "retour possible", "moyen approprié"]}]}, {"position": 3, "label": "Consigner la mention explicite de cette information à venir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Précaution évitant l''oubli de cet élément.", "groups": [{"position": 1, "keywords": ["information consignée", "mention explicite", "oubli évité"]}]}, {"position": 4, "label": "Rappeler l''utilité de ce dispositif pour de futurs achats", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information utile au-delà de cette affaire.", "groups": [{"position": 1, "keywords": ["utilité rappelée", "futurs achats", "au-delà de l''affaire"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment exploitez-vous ce dispositif d''identification une fois le numéro transmis pour maximiser les chances de restitution ?", "hint": "Une fois ce numéro obtenu, son exploitation doit être organisée méthodiquement pour maximiser les chances de retrouver ce vélo identifié.", "perfect": "Je m''assure, une fois ce numéro reçu, de l''intégrer sans délai au signalement de ce vélo volé, cette mise à jour étant nécessaire pour une exploitation optimale de ce dispositif d''identification.\n\nJe vérifie que ce numéro soit correctement enregistré dans les systèmes appropriés permettant une éventuelle identification lors de contrôles ultérieurs de vélos suspects.\n\nJe reste attentive à informer cette victime des chances réalistes de restitution grâce à ce dispositif, sans lui donner de faux espoirs disproportionnés sur les probabilités effectives de retrouver ce bien.\n\nJe lui indique les démarches complémentaires possibles, comme la surveillance des plateformes de revente en ligne, ce complément pouvant utilement s''ajouter à l''exploitation de ce seul marquage antivol.", "points": [{"position": 1, "label": "Intégrer sans délai ce numéro au signalement une fois reçu", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : mise à jour pour une exploitation optimale.", "groups": [{"position": 1, "keywords": ["numéro intégré", "signalement mis à jour", "exploitation optimale"]}]}, {"position": 2, "label": "Vérifier l''enregistrement correct dans les systèmes appropriés", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ident